def docs_updated_for_quest(repo_path: Path, base_ref: str) -> bool:
    if not base_ref:
        return False
    checks: list[list[str]] = [
        ["diff", "--name-only", base_ref, "HEAD", "--", "docs"],
        ["diff", "--name-only", base_ref, "--", "docs"],
        ["ls-files", "--others", "--exclude-standard", "--", "docs"],
    ]
    for args in checks:
        proc = subprocess.run(
            ["git", "-C", str(repo_path), *args],
            capture_output=True,
            text=True,
        )
        if proc.returncode == 0 and any(x.strip() for x in proc.stdout.splitlines()):
            return True
    return False


